/**
 * Elasticsearch index definition for evidence cards.
 *
 * The app owns this (it used to be generated by pgsync, whose analyzer setting was never applied, so search ran on
 * default analysis with no stemming). Reads and writes go through the `evidence` alias, so a reindex can build a
 * new index next to the live one and swap them atomically.
 */
export const INDEX_ALIAS = process.env.ELASTICSEARCH_INDEX || 'evidence';

/** Searchable text fields, in no particular order. Weights live in the query builder. */
export const TEXT_FIELDS = ['tag', 'cite', 'fullcite', 'summary', 'spoken', 'fulltext', 'pocket', 'hat', 'block'] as const;
export type TextField = typeof TEXT_FIELDS[number];

export const indexSettings = {
  // One node, so no replicas (they would leave the index yellow forever). One shard is plenty below ~50GB.
  number_of_shards: 1,
  number_of_replicas: 0,
  // New cards become searchable within 5s; the default 1s makes a bulk load create a segment per second.
  refresh_interval: '5s',
  analysis: {
    filter: {
      english_possessive: { type: 'stemmer', language: 'possessive_english' },
      english_stem: { type: 'stemmer', language: 'english' },
    },
    analyzer: {
      // Stems ("regulation"/"regulations"/"regulate" all match) and folds accents, but deliberately has NO stop
      // word filter: the built-in `english` analyzer drops "no" and "not", which are meaningful in debate
      // ("no link", "not unique").
      debate_text: {
        type: 'custom',
        tokenizer: 'standard',
        filter: ['english_possessive', 'lowercase', 'asciifolding', 'english_stem'],
      },
    },
  },
};

const text = { type: 'text', analyzer: 'debate_text' } as const;

export const indexMappings = {
  // Documents are built by src/modules/search/documents.ts, so an unexpected field is a bug worth failing on
  dynamic: 'strict',
  properties: {
    id: { type: 'integer' },
    gid: { type: 'keyword' },
    bucketId: { type: 'integer' },
    // Cards in the same duplicate bucket share a key; a card with no bucket yet is its own group ("b12" / "c34",
    // prefixed so bucket and card ids can never collide). Search collapses on this.
    groupKey: { type: 'keyword' },
    // How many cards are in this card's bucket, used to nudge popular cards up
    duplicateCount: { type: 'integer' },
    // Names of the tags on the card's file, matched exactly (case sensitive)
    tags: { type: 'keyword' },
    ...Object.fromEntries(TEXT_FIELDS.map((field) => [field, text])),
  },
} as const;
